            return d >= dayStart && d < dayEnd;
          }).length;
          els.wakesToday.textContent = todaysCount;
          els.wakesRemaining.textContent = 16 - todaysCount;

          const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
          const weekCount = log.filter(function (t) {
