      const progress = Math.min(elapsed, 90) * 100 / 90;
      els.wakeProgress.value = Math.min(elapsed, 90);
      els.wakeProgressText.textContent = remaining + " minute" + (remaining === 1 ? "" : "s") + " remaining";
